-- Generated by rehearsal/build_sql.py. Edit the generator, not this file.
-- Run only with psql, as described in 2026-11-18_phase1_render.md:
--   psql -X -v ON_ERROR_STOP=1 "<connection>" -f <this file>; echo "exit code: $?"
-- Exit code 0 = success. Anything else = stopped; read the message above it.
\set ON_ERROR_STOP on
\set ON_ERROR_ROLLBACK off
\set QUIET on
\pset pager off

-- PRE-CHECK. Read-only: runs in a READ ONLY transaction and is always rolled back. Changes nothing.
-- Stops (exit code 3) and lists every difference if the database is not exactly as reviewed on 18 Nov 2026.
BEGIN TRANSACTION READ ONLY;
DO $precheck$
DECLARE
  problems text[] := '{}';
  exp jsonb; act jsonb; k text; n bigint; v_type text; v_null text; v_def text;
BEGIN
  -- Right database. (A rehearsal on a local copy sets vah.rehearsal=on; Render never does.)
  IF current_database() <> 'vah_postgres_40zq' AND current_setting('vah.rehearsal', true) IS DISTINCT FROM 'on' THEN
    problems := problems || format('connected to database %s, expected vah_postgres_40zq', current_database());
  END IF;
  IF current_setting('server_version_num')::int < 130000 THEN
    problems := problems || format('PostgreSQL %s is older than 13', current_setting('server_version'));
  END IF;

  -- Structure reviewed on 18 Nov 2026: every table's columns (name, type, nullability) must match exactly.
  exp := '{"_migrations": "a0de9cf4", "activity_log": "13bf436c", "address_slot": "b9c204ee", "admin_activity": "3df72fa1", "admin_audit": "3c95dd75", "admin_log": "75bb2f45", "admin_operation_locks": "9d3df15c", "audit_log": "218091fa", "blog_posts": "bd8b6505", "business": "5c794a24", "business_owner": "d9a32ba8", "business_owner_invite": "a9f85e5e", "charge": "30217ad9", "concurrent_operations": "a77874f6", "destruction_log": "4237c23a", "download": "9eafe1c7", "email_change_request": "ed9576e8", "email_preferences": "f9033cb3", "export_job": "3d736eba", "file": "13e93dfb", "forwarding_charge": "91e85dc5", "forwarding_outbox": "30f28f65", "forwarding_request": "5727c82a", "gc_billing_request_flow": "889502f0", "gc_redirect_flow": "9ade8bf7", "invoice_token": "5c621682", "invoices": "7d889641", "invoices_seq": "23b84d07", "kyc_status": "35b707eb", "location": "3393641c", "mail_event": "c4d7f841", "mail_item": "b27f6f07", "migrations": "0831a78a", "notification": "878b53d1", "password_reset": "1ace3ab7", "plan_price_history": "4ef1d354", "plan_status_event": "899e7e4c", "plans": "05545746", "quiz_leads": "60f14d45", "scan_tokens": "d632de93", "subscription": "d58ab948", "support_ticket": "eab1a130", "usage_charges": "cdf54800", "user": "8471fc33", "user_profile": "6eaa50de", "user_profile_view": "dd999a95", "webhook_log": "7c36ec9b"}'::jsonb;
  SELECT jsonb_object_agg(t, h) INTO act FROM (SELECT table_name AS t, left(md5(string_agg(column_name||':'||data_type||':'||is_nullable, ',' ORDER BY column_name)), 8) AS h
                 FROM information_schema.columns WHERE table_schema = 'public' GROUP BY table_name) f;
  FOR k IN SELECT jsonb_object_keys(exp) LOOP
    IF act->>k IS DISTINCT FROM exp->>k THEN
      problems := problems || format('table %s: column fingerprint %s, expected %s', k, coalesce(act->>k, 'MISSING'), exp->>k);
    END IF;
  END LOOP;
  FOR k IN SELECT jsonb_object_keys(act) LOOP
    IF NOT exp ? k THEN problems := problems || format('unexpected table %s', k); END IF;
  END LOOP;

  -- Objects this change replaces or relies on, exactly as reviewed.

  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_user_period_unique'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_user_period_unique ON public.invoices USING btree (user_id, period_start, period_end)' THEN
    problems := problems || format('index idx_invoices_user_period_unique: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_user_period_unique'), 'MISSING'));
  END IF;

  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_stripe_invoice_id'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_stripe_invoice_id ON public.invoices USING btree (stripe_invoice_id) WHERE (stripe_invoice_id IS NOT NULL)' THEN
    problems := problems || format('index idx_invoices_stripe_invoice_id: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_stripe_invoice_id'), 'MISSING'));
  END IF;

  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_gocardless_payment_id'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_gocardless_payment_id ON public.invoices USING btree (gocardless_payment_id) WHERE (gocardless_payment_id IS NOT NULL)' THEN
    problems := problems || format('index idx_invoices_gocardless_payment_id: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_gocardless_payment_id'), 'MISSING'));
  END IF;

  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'subscription_user_unique'), 'MISSING') <> 'CREATE UNIQUE INDEX subscription_user_unique ON public.subscription USING btree (user_id)' THEN
    problems := problems || format('index subscription_user_unique: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'subscription_user_unique'), 'MISSING'));
  END IF;

  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_seq_year'), 'MISSING') <> 'CREATE INDEX idx_invoices_seq_year ON public.invoices_seq USING btree (year)' THEN
    problems := problems || format('index idx_invoices_seq_year: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_seq_year'), 'MISSING'));
  END IF;

  IF EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_seq_year_new') THEN
    problems := problems || text 'index idx_invoices_seq_year_new already exists';
  END IF;

  IF EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_created') THEN
    problems := problems || text 'index idx_notification_user_created already exists';
  END IF;

  -- Indexes, constraints and triggers reviewed on 18 Nov 2026: every index definition, constraint and trigger must match exactly.
  SELECT (SELECT md5(string_agg(md5(indexdef), '' ORDER BY md5(indexdef) COLLATE "C")) FROM pg_indexes WHERE schemaname = 'public') INTO v_def;
  IF v_def IS DISTINCT FROM 'fc0437965cbb71aa7e0b16e8b8573fbf' THEN
    problems := problems || format('index definitions differ from the expected set (fingerprint %s, expected fc0437965cbb71aa7e0b16e8b8573fbf)', v_def);
  END IF;
  SELECT (SELECT md5(string_agg(h, '' ORDER BY h COLLATE "C")) FROM (SELECT md5(conrelid::regclass::text || ':' || conname || ':' || pg_get_constraintdef(oid)) AS h FROM pg_constraint WHERE connamespace = 'public'::regnamespace AND contype <> 'n') x) INTO v_def;
  IF v_def IS DISTINCT FROM 'a7de2267504b6f422c1cd0d67855d90d' THEN
    problems := problems || format('constraints differ from the expected set (fingerprint %s, expected a7de2267504b6f422c1cd0d67855d90d)', v_def);
  END IF;
  SELECT (SELECT md5(string_agg(md5(pg_get_triggerdef(oid)), '' ORDER BY 1)) FROM pg_trigger WHERE NOT tgisinternal) INTO v_def;
  IF v_def IS DISTINCT FROM 'ce480cbc816118c5fc846d98ac56012d' THEN
    problems := problems || format('triggers differ from the expected set (fingerprint %s, expected ce480cbc816118c5fc846d98ac56012d)', v_def);
  END IF;

  IF EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_provider_payment_id') THEN
    problems := problems || text 'index idx_invoices_provider_payment_id already exists';
  END IF;

  IF EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_unread') THEN
    problems := problems || text 'index idx_notification_user_unread already exists';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indrelid
              WHERE c.relname = 'invoices_seq' AND i.indisunique AND NOT i.indisprimary) THEN
    problems := problems || text 'invoices_seq already has a unique index other than its primary key';
  END IF;
  -- Check constraints on subscription: exactly the GoCardless mandate check.
  SELECT count(*) INTO n FROM pg_constraint WHERE conrelid = 'public.subscription'::regclass AND contype = 'c';
  IF n <> 1 OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.subscription'::regclass
                            AND conname = 'subscription_active_requires_mandate'
                            AND replace(pg_get_constraintdef(oid), ' NOT VALID', '') = 'CHECK (((status <> ''active''::text) OR (mandate_id IS NOT NULL)))') THEN
    problems := problems || format('subscription check constraints differ from the review (%s found)', n);
  END IF;
  -- None of the tracked migrations recorded yet.
  SELECT count(*) INTO n FROM migrations WHERE name = ANY (ARRAY['20261115_01_notification_and_audit_tables.sql', '20261115_02_backfill_primary_business.sql', '20261115_03_stripe_entitlement.sql', '20261115_04_invoice_period_unique_for_internal_only.sql', '20261117_01_login_throttle.sql']::text[]);
  IF n > 0 THEN problems := problems || format('%s of the Phase 1 migrations are already recorded in the migrations table', n); END IF;
  -- Data that would make the new unique index fail.
  SELECT count(*) INTO n FROM (SELECT year FROM invoices_seq GROUP BY year HAVING count(*) > 1) d;
  IF n > 0 THEN problems := problems || format('invoices_seq has %s duplicated year(s)', n); END IF;

  -- Information only (not a failure): what the data steps will touch.
  RAISE NOTICE 'customers without a business (will get one): %',
    (SELECT count(*) FROM "user" u WHERE NOT u.is_admin AND u.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM business b WHERE b.user_id = u.id));
  RAISE NOTICE 'notification rows to convert to millisecond timestamps: %', (SELECT count(*) FROM notification);
  RAISE NOTICE 'active subscriptions without a Stripe subscription (will show Payment needed): %',
    (SELECT count(*) FROM subscription WHERE status = 'active' AND stripe_subscription_id IS NULL);
  IF cardinality(problems) > 0 THEN
    RAISE EXCEPTION 'PRECHECK FAILED: nothing was changed (% problem(s)):%', cardinality(problems), E'\n  - ' || array_to_string(problems, E'\n  - ');
  END IF;
  RAISE NOTICE 'PRECHECK PASSED';
END
$precheck$;
ROLLBACK;
\echo 'PRECHECK PASSED: the database matches the review. Next: take the backup, then run the migration file.'
